  const raw = JSON.stringify(event("evt_http"));
  const now = Math.floor(Date.now() / 1000);
  const before = snapshot(dir);
  for (const [body, header] of [[raw, null], [raw, signed(raw, now, "wrong")],
    [raw, signed(raw, now - 301)], [raw, signed(raw, now + 3600)],
    [raw + " ", signed(raw, now)], ["not-json", signed("not-json", now, "wrong")]] as const) {
    assert.equal((await post(body, header)).status, 401);
    assert.deepEqual(snapshot(dir), before);
  }
  assert.equal(store.listRefunds().length, 0);
  for (const body of ["not-json", "null", JSON.stringify(event("evt_invalid", "refund.requested", { amount: -1 }))]) {
    assert.equal((await post(body)).status, 400);
    assert.deepEqual(snapshot(dir), before);
  }
});

test("HTTP concurrent retries and altered duplicate bodies do not mutate anything again", async (t) => {
  const { post, dir, store } = await receiver(t);
  const raw = JSON.stringify(event("evt_retries"), null, 2);
  const responses = await Promise.all(Array.from({ length: 5 }, () => post(raw)));
  assert.ok(responses.every((r) => r.status === 200 && r.body.received === true));
  assert.equal(responses.filter((r) => r.body.duplicate === false).length, 1);
  assert.equal(responses.filter((r) => r.body.duplicate === true).length, 4);
  assert.equal(store.listRefunds().length, 1);
  const before = snapshot(dir);
  assert.deepEqual(await post(JSON.stringify(event("evt_retries", "refund.requested", { amount: 999_999 }))),
    { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), before);
  assert.equal(store.loadRawEvent("evt_retries"), raw);
});

test("HTTP cancellation and ignored events are also idempotent", async (t) => {
  const { post, dir, store } = await receiver(t);
  assert.equal((await post(JSON.stringify(event("evt_pending", "refund.requested", { amount: 500_001 })))).status, 200);
  const cancelled = JSON.stringify(event("evt_cancel", "refund.cancelled"));
  assert.deepEqual(await post(cancelled), { status: 200, body: { received: true, duplicate: false } });
  assert.equal(store.listRefunds()[0].status, "cancelled");
  const before = snapshot(dir);
  assert.deepEqual(await post(cancelled), { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), before);

  const ignored = JSON.stringify({ event_id: "evt_other", type: "payment.updated", created: NOW });
  assert.deepEqual(await post(ignored), { status: 200, body: { received: true, duplicate: false } });
  const afterIgnored = snapshot(dir);
  assert.deepEqual(await post(ignored), { status: 200, body: { received: true, duplicate: true } });
  assert.deepEqual(snapshot(dir), afterIgnored);
  assert.ok(existsSync(join(dir, "state.json")));
});

test("cancellation of an auto-approved refund is audited only once", (t) => {
  const { store, dir } = tempStore(t);
  processEvent(store, POLICY, parseEvent(JSON.stringify(event("evt_approved"))));
  const cancellation = parseEvent(JSON.stringify(event("evt_ignore_cancel", "refund.cancelled")));
  assert.equal(processEvent(store, POLICY, cancellation).outcome, "ignored");
  assert.equal(store.listRefunds()[0].status, "auto_approved");
  const before = snapshot(dir);
  assert.equal(processEvent(store, POLICY, cancellation).outcome, "duplicate");
  assert.deepEqual(snapshot(dir), before);
  const audit = readFileSync(join(dir, "audit.jsonl"), "utf8").trim().split("\n").map((s) => JSON.parse(s));
  assert.equal(audit.filter((e) => e.action === "cancel.ignored").length, 1);
});
